el.onpointermove=ev=>{mv=1;const dx=(ev.clientX-x0)/b.width*100,dy=(ev.clientY-y0)/b.height*100;if(rs){q.w=Math.max(5,Math.min(100-o.x,o.w+dx));q.h=Math.max(5,Math.min(100-o.y,o.h+dy))}else{q.x=Math.max(0,Math.min(100-o.w,o.x+dx));q.y=Math.max(0,Math.min(100-o.h,o.y+dy))}Object.assign(el.style,{left:q.x+'%',top:q.y+'%',width:q.w+'%',height:q.h+'%'})};
