addReg(){const n=D.regions.length+1;D.regions.push({id:n,name:D.name+'-'+n,x:5*n%40,y:5*n%40,w:40,h:40,items:[]});sr=n-1;si=-1;designer(D.id)},selI(i,a){sr=+a.dataset.r;si=+i;designer(D.id)},
